import CryptoKit
import XCTest
@testable import OnymMesh

/// The cross-platform contract: `Fixtures/mesh-v1-vectors.json` was
/// generated by a separate implementation of the spec, and Android and
/// the station firmware check against the same file. A change here that
/// isn't a deliberate protocol version bump is a bug.
final class MeshVectorsTests: XCTestCase {
    private struct Vectors: Decodable {
        struct TagVector: Decodable { let epoch: UInt32; let tag: String }
        let alicePrivateKey: String
        let alicePublicKey: String
        let bobPrivateKey: String
        let bobPublicKey: String
        let pairKey: String
        let date: String
        let epoch: UInt32
        let tags: [TagVector]
        let envelopeHex: String
        let envelopeID: String
        let maxFrameSize: Int
        let frames: [String]
        let compactEnvelopeID: String
        let compactMaxChunk: Int
        let compactFrames: [String]
    }

    private var v: Vectors!

    override func setUpWithError() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "mesh-v1-vectors", withExtension: "json", subdirectory: "Fixtures"))
        v = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testPairKeyIsTheSameFromEitherSide() throws {
        let alice = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: hex(v.alicePrivateKey))
        let bob = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: hex(v.bobPrivateKey))
        XCTAssertEqual(alice.publicKey.rawRepresentation, hex(v.alicePublicKey))
        XCTAssertEqual(bob.publicKey.rawRepresentation, hex(v.bobPublicKey))

        let fromAlice = try MeshPairKey.derive(privateKey: alice, peerPublicKey: hex(v.bobPublicKey))
        let fromBob = try MeshPairKey.derive(privateKey: bob, peerPublicKey: hex(v.alicePublicKey))
        XCTAssertEqual(fromAlice, hex(v.pairKey))
        XCTAssertEqual(fromBob, hex(v.pairKey))
    }

    func testEpochAndTags() throws {
        let date = try XCTUnwrap(ISO8601DateFormatter().date(from: v.date))
        XCTAssertEqual(MeshEpoch.number(at: date), v.epoch)
        for t in v.tags {
            XCTAssertEqual(MeshTag.derive(pairKey: hex(v.pairKey), epoch: t.epoch).bytes, hex(t.tag), "epoch \(t.epoch)")
        }
    }

    func testFramesEncodeAndReassemble() throws {
        let tag = MeshTag.derive(pairKey: hex(v.pairKey), epoch: v.epoch)
        let id = UInt64(v.envelopeID, radix: 16)!
        let frames = try XCTUnwrap(MeshFrame.fragment(
            envelope: hex(v.envelopeHex), tag: tag, epoch: v.epoch,
            envelopeID: id, maxFrameSize: v.maxFrameSize
        ))
        XCTAssertEqual(frames.map { $0.bytes }, v.frames.map(hex))

        var reassembler = MeshReassembler()
        let decoded = try v.frames.reversed().map { try XCTUnwrap(MeshFrame(bytes: hex($0))) }
        let results = decoded.map { reassembler.add($0, at: Date()) }
        XCTAssertEqual(results.compactMap { $0 }, [hex(v.envelopeHex)])
    }

    func testCompactFramesEncodeAndResolve() throws {
        let tag = MeshTag.derive(pairKey: hex(v.pairKey), epoch: v.epoch)
        let id = UInt16(v.compactEnvelopeID, radix: 16)!
        let frames = try XCTUnwrap(MeshCompactFrame.fragment(
            envelope: hex(v.envelopeHex), tag: tag, epoch: v.epoch,
            envelopeID: id, maxChunk: v.compactMaxChunk
        ))
        XCTAssertEqual(frames.map { $0.bytes }, v.compactFrames.map(hex))

        // A receiver recovers the full epoch from the low byte, then
        // reassembles through the shared v1 path.
        var reassembler = MeshReassembler()
        var out: [Data] = []
        for bytes in v.compactFrames.map(hex) {
            let compact = try XCTUnwrap(MeshCompactFrame(bytes: bytes))
            let epoch = try XCTUnwrap(MeshCompactFrame.resolveEpoch(low: compact.epochLow, oldest: v.epoch - 96, current: v.epoch))
            XCTAssertEqual(epoch, v.epoch)
            if let e = reassembler.add(compact.meshFrame(epoch: epoch), at: Date()) { out.append(e) }
        }
        XCTAssertEqual(out, [hex(v.envelopeHex)])
    }
}

func hex(_ string: String) -> Data {
    var data = Data()
    var index = string.startIndex
    while index < string.endIndex {
        let next = string.index(index, offsetBy: 2)
        data.append(UInt8(string[index..<next], radix: 16)!)
        index = next
    }
    return data
}
